cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <climits>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int N>
struct alignas(16) AlignedVector {
    T v[N];
};
__device__ __forceinline__ bool is_aligned_16(const void* ptr) {
    return (reinterpret_cast<unsigned long long>(ptr) & 15ull) == 0ull;
}
template <int BLOCK_THREADS>
__device__ __forceinline__ float warp_reduce_sum(float value) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        value += __shfl_down_sync(0xffffffff, value, offset);
    }
    return value;
}
template <int BLOCK_THREADS>
__device__ __forceinline__ float block_reduce_sum(
    float value, float* shared) {
    constexpr int WARP_SIZE = 32;
    constexpr int NUM_WARPS = BLOCK_THREADS / WARP_SIZE;
    int tid = static_cast<int>(threadIdx.x);
    int lane = tid & (WARP_SIZE - 1);
    int warp_id = tid / WARP_SIZE;
    value = warp_reduce_sum<BLOCK_THREADS>(value);
    if (lane == 0) {
        shared[warp_id] = value;
    }
    __syncthreads();
    value = (tid < NUM_WARPS) ? shared[tid] : 0.0f;
    if (warp_id == 0) {
        value = warp_reduce_sum<BLOCK_THREADS>(value);
    }
    __syncthreads();
    return value;
}
__device__ __forceinline__ void combine_welford(
    int& a_count, float& a_mean, float& a_m2,
    int b_count, float b_mean, float b_m2) {
    if (b_count == 0) {
        return;
    }
    if (a_count == 0) {
        a_count = b_count;
        a_mean = b_mean;
        a_m2 = b_m2;
        return;
    }
    int total = a_count + b_count;
    float delta = b_mean - a_mean;
    a_mean += delta * (static_cast<float>(b_count) /
                      static_cast<float>(total));
    a_m2 += b_m2 + delta * delta *
            (static_cast<float>(a_count) * static_cast<float>(b_count) /
             static_cast<float>(total));
    a_count = total;
}
template <typename scalar_t, int BLOCK_THREADS>
__global__ __launch_bounds__(BLOCK_THREADS, 2) void cute_layer_norm_kernel(
    const scalar_t* __restrict__ x_ptr,
    const scalar_t* __restrict__ weight_ptr,
    const scalar_t* __restrict__ bias_ptr,
    scalar_t* __restrict__ out_ptr,
    int rows,
    int cols,
    float eps)
{
    constexpr int VEC_WIDTH = 16 / sizeof(scalar_t);
    static_assert(16 % sizeof(scalar_t) == 0,
                  "scalar_t must divide a 16-byte vector");
    constexpr int WARP_SIZE = 32;
    constexpr int NUM_WARPS = BLOCK_THREADS / WARP_SIZE;
    int row = static_cast<int>(blockIdx.x);
    int tid = static_cast<int>(threadIdx.x);
    int lane = tid & (WARP_SIZE - 1);
    int warp_id = tid >> 5;
    if (row >= rows) {
        return;
    }
    auto x = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));
    auto out = make_tensor(
        make_gmem_ptr(out_ptr),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));
    auto weight = make_tensor(
        make_gmem_ptr(weight_ptr),
        make_shape(cols),
        make_stride(Int<1>{}));
    auto bias = make_tensor(
        make_gmem_ptr(bias_ptr),
        make_shape(cols),
        make_stride(Int<1>{}));
    __shared__ float warp_mean[NUM_WARPS];
    __shared__ float warp_m2[NUM_WARPS];
    __shared__ int warp_count[NUM_WARPS];
    __shared__ float mean_storage;
    __shared__ float inv_std_storage;
    const scalar_t* row_x = x_ptr + static_cast<size_t>(row) * cols;
    scalar_t* row_out = out_ptr + static_cast<size_t>(row) * cols;
    bool use_vectorized =
        (cols % VEC_WIDTH == 0) &&
        is_aligned_16(row_x) &&
        is_aligned_16(row_out) &&
        is_aligned_16(weight_ptr) &&
        is_aligned_16(bias_ptr);
    int local_count = 0;
    float local_mean = 0.0f;
    float local_m2 = 0.0f;
    if (use_vectorized) {
        using Vec = AlignedVector<scalar_t, VEC_WIDTH>;
        const Vec* x_vec = reinterpret_cast<const Vec*>(row_x);
        int vector_count = cols / VEC_WIDTH;
        for (int v = tid; v < vector_count; v += BLOCK_THREADS) {
            Vec values = x_vec[v];
            #pragma unroll
            for (int k = 0; k < VEC_WIDTH; ++k) {
                float value = static_cast<float>(values.v[k]);
                int next_count = local_count + 1;
                float delta = value - local_mean;
                local_mean += delta / static_cast<float>(next_count);
                float delta2 = value - local_mean;
                local_m2 += delta * delta2;
                local_count = next_count;
            }
        }
    } else {
        for (int col = tid; col < cols; col += BLOCK_THREADS) {
            float value = static_cast<float>(x(row, col));
            int next_count = local_count + 1;
            float delta = value - local_mean;
            local_mean += delta / static_cast<float>(next_count);
            float delta2 = value - local_mean;
            local_m2 += delta * delta2;
            local_count = next_count;
        }
    }
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        int other_count = __shfl_down_sync(0xffffffff, local_count, offset);
        float other_mean = __shfl_down_sync(0xffffffff, local_mean, offset);
        float other_m2 = __shfl_down_sync(0xffffffff, local_m2, offset);
        combine_welford(local_count, local_mean, local_m2,
                        other_count, other_mean, other_m2);
    }
    if (lane == 0) {
        warp_count[warp_id] = local_count;
        warp_mean[warp_id] = local_mean;
        warp_m2[warp_id] = local_m2;
    }
    __syncthreads();
    if (tid == 0) {
        int total_count = warp_count[0];
        float total_mean = warp_mean[0];
        float total_m2 = warp_m2[0];
        for (int w = 1; w < NUM_WARPS; ++w) {
            combine_welford(total_count, total_mean, total_m2,
                            warp_count[w], warp_mean[w], warp_m2[w]);
        }
        mean_storage = total_mean;
        inv_std_storage = rsqrtf(
            total_m2 / static_cast<float>(total_count) + eps);
    }
    __syncthreads();
    const float mean = mean_storage;
    const float inv_std = inv_std_storage;
    if (use_vectorized) {
        using Vec = AlignedVector<scalar_t, VEC_WIDTH>;
        const Vec* x_vec = reinterpret_cast<const Vec*>(row_x);
        const Vec* weight_vec = reinterpret_cast<const Vec*>(weight_ptr);
        const Vec* bias_vec = reinterpret_cast<const Vec*>(bias_ptr);
        Vec* out_vec = reinterpret_cast<Vec*>(row_out);
        int vector_count = cols / VEC_WIDTH;
        for (int v = tid; v < vector_count; v += BLOCK_THREADS) {
            Vec xv = x_vec[v];
            Vec wv = weight_vec[v];
            Vec bv = bias_vec[v];
            Vec ov;
            #pragma unroll
            for (int k = 0; k < VEC_WIDTH; ++k) {
                float value = (static_cast<float>(xv.v[k]) - mean) * inv_std;
                value = value * static_cast<float>(wv.v[k]) +
                        static_cast<float>(bv.v[k]);
                ov.v[k] = static_cast<scalar_t>(value);
            }
            out_vec[v] = ov;
        }
    } else {
        for (int col = tid; col < cols; col += BLOCK_THREADS) {
            float value = (static_cast<float>(x(row, col)) - mean) * inv_std;
            value = value * static_cast<float>(weight(col)) +
                    static_cast<float>(bias(col));
            out(row, col) = static_cast<scalar_t>(value);
        }
    }
}


torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");
    TORCH_CHECK(weight.dim() >= 1, "weight must have at least one dimension");
    TORCH_CHECK(bias.dim() == weight.dim(),
                "bias and weight must have the same number of dimensions");
    TORCH_CHECK(weight.sizes() == bias.sizes(),
                "bias and weight must have the same shape");
    TORCH_CHECK(x.dim() >= weight.dim(),
                "input must have at least as many dimensions as normalized_shape");
    const int64_t normalized_rank = weight.dim();
    const int64_t x_start_dim = x.dim() - normalized_rank;
    for (int64_t i = 0; i < normalized_rank; ++i) {
        TORCH_CHECK(
            x.size(x_start_dim + i) == weight.size(i),
            "input trailing dimensions must match normalized_shape");
    }
    TORCH_CHECK(weight.numel() > 0,
                "normalized_shape must contain at least one element");
    TORCH_CHECK(x.numel() % weight.numel() == 0,
                "input size must be divisible by normalized size");
    TORCH_CHECK(x.scalar_type() == weight.scalar_type(),
                "x and weight must have the same dtype");
    TORCH_CHECK(x.scalar_type() == bias.scalar_type(),
                "x and bias must have the same dtype");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kHalf ||
        x.scalar_type() == at::kBFloat16,
        "supported dtypes are float32, float16, and bfloat16");

    auto x_contiguous = x.contiguous();
    auto weight_contiguous = weight.contiguous();
    auto bias_contiguous = bias.contiguous();
    auto output = torch::empty_like(x_contiguous);

    int64_t cols64 = weight_contiguous.numel();
    int64_t rows64 = x_contiguous.numel() / cols64;

    TORCH_CHECK(cols64 <= INT_MAX, "normalized dimension is too large");
    TORCH_CHECK(rows64 <= INT_MAX, "number of rows is too large");

     constexpr int BLOCK_THREADS = 256;
    dim3 block(BLOCK_THREADS);
    dim3 grid(static_cast<unsigned int>(rows64));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half,
        at::ScalarType::BFloat16,
        x_contiguous.scalar_type(),
        "cute_layer_norm",
        [&] {
            cute_layer_norm_kernel<scalar_t, BLOCK_THREADS>
                <<<grid, block, 0, stream>>>(
                    x_contiguous.data_ptr<scalar_t>(),
                    weight_contiguous.data_ptr<scalar_t>(),
                    bias_contiguous.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    static_cast<int>(rows64),
                    static_cast<int>(cols64),
                    static_cast<float>(eps));
        });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE layer normalization kernel launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return cute_ext.cute_layer_norm(
            x,
            self.ln.weight,
            self.ln.bias,
            self.ln.eps,
        )

